69	// What the chat shows for one trace, and what the fixer is told it read.
70	function summarize(trace, spans) {
71	  const ordered = [...spans].sort((a, b) => String(a.startedAt).localeCompare(String(b.startedAt)));
72	  const sequence = [];
73	  for (const span of ordered.filter((s) => s.spanType === "TOOL")) {
74	    const name = spanName(span);
75	    const last = sequence.at(-1);
76	    if (last?.name === name && last.error === failed(span)) last.n++;
77	    else sequence.push({ name, n: 1, error: failed(span) });
78	  }
79	  return {
80	    traceId: trace.traceId || trace.trace_id || trace.id,
81	    status: trace.status,
82	    finalized: trace.finalizationStatus === "finalized",
83	    spans: trace.spansCount ?? spans.length,
84	    toolCalls: trace.toolCallsCount ?? ordered.filter((s) => s.spanType === "TOOL").length,
85	    llmCalls: trace.llmCallsCount ?? ordered.filter((s) => s.spanType === "LLM").length,
86	    tokens: trace.totalTokens ?? null,
87	    costUsd: trace.totalCostUsd ?? null,
88	    durationMs: trace.durationMs ?? null,
89	    errors: ordered.filter(failed).map((s) => ({ name: spanName(s), type: s.spanType, durationMs: s.durationMs })),
90	    sequence: sequence.slice(0, 40),
91	  };
92	}
