8	const LIVE_MS = 6000;
9	const SETTLE_MS = 10000;
10	const SETTLE_TRIES = 12;
11	
12	const entries = new Map();
13	
14	function entry(id) {
15	  if (!entries.has(id)) entries.set(id, { ev: null, after: 0, live: false, timer: null, inflight: false, subs: new Set() });
16	  return entries.get(id);
17	}
