19	const finalized = (ev) => Boolean(ev?.matched && ev.traces[0]?.summary?.finalized);
20	
21	function settled(e) {
22	  if (e.ev?.configured === false) return true;
23	  if (e.live) return false;
24	  return finalized(e.ev) || e.after >= SETTLE_TRIES;
25	}
26	
27	function schedule(id) {
28	  const e = entry(id);
29	  if (e.timer || e.inflight || !e.subs.size || settled(e)) return;
30	  e.timer = setTimeout(() => {
31	    e.timer = null;
32	    e.inflight = true;
33	    call("studio:evidence", { sessionId: id })
34	      .catch((err) => ({ matched: false, traces: [], error: err.message }))
35	      .then((ev) => {
36	        e.inflight = false;
37	        e.ev = ev;
38	        if (!e.live) e.after++;
39	        e.subs.forEach((fn) => fn());
40	        schedule(id);
41	      });
42	  }, e.ev ? (e.live ? LIVE_MS : SETTLE_MS) : 0);
43	}
