45	function watch(id, live, fn) {
46	  const e = entry(id);
47	  e.live = live;
48	  e.subs.add(fn);
49	  schedule(id);
50	  return () => {
51	    e.subs.delete(fn);
52	    if (!e.subs.size) {
53	      clearTimeout(e.timer);
54	      e.timer = null;
55	    }
56	  };
57	}
