65	function view(id) {
66	  const e = entries.get(id);
67	  const ev = e?.ev;
68	  const trace = ev?.matched ? ev.traces[0] : null;
69	  let state;
70	  if (ev?.configured === false) state = "off";
71	  else if (e?.live) state = "live";
72	  else if (finalized(ev)) state = "matched";
73	  else if (trace) state = "finalizing";
74	  else if (!ev || e.after < SETTLE_TRIES) state = "looking";
75	  else state = ev.error ? "error" : "none";
76	  return { state, ev, trace, summary: trace?.summary || null };
77	}
