79	/** `sessions`: [{ sessionId, live }]. Returns { [sessionId]: { state, ev, trace, summary } }. */
80	export function useTraces(sessions) {
81	  const [, bump] = React.useReducer((x) => x + 1, 0);
82	  const list = sessions.filter((s) => s.sessionId);
83	  const key = list.map((s) => `${s.sessionId}:${s.live ? 1 : 0}`).join(",");
84	  React.useEffect(() => {
85	    const offs = list.map((s) => watch(s.sessionId, s.live, bump));
86	    return () => offs.forEach((off) => off());
87	  }, [key]);
88	  return Object.fromEntries(list.map((s) => [s.sessionId, view(s.sessionId)]));
89	}
